1	# Local-development reverse proxy. Prescribed by
2	# context/project-structure.md's required docker/ tree
3	# (docker/nginx/nginx.conf) — nginx is the required proxy technology, not
4	# an open choice (see docs/architecture/local-stack-inventory.md §8).
5	#
6	# This is a minimal dev-only config: no TLS, no caching, no production
7	# hardening, no rate limiting. It exists only to:
8	#   1. Give the browser ONE host-reachable origin for both the web app
9	#      and the API, so NEXT_PUBLIC_API_URL can point here instead of at
10	#      apps/api's internal container port (which is never published to
11	#      the host — see docker-compose.yml and
12	#      docs/architecture/docker-compose-stack.md).
13	#   2. Satisfy "expose health/readiness endpoints only through the local
14	#      reverse proxy" for apps/api's existing GET /health and GET /ready.
15	#
16	# Because both the page (served at "/") and the API (served at "/api/")
17	# are reached through this SAME origin, the browser's calls to
18	# NEXT_PUBLIC_API_URL become same-origin requests — no CORS exemption is
19	# relied upon for them to work (API_CORS_ORIGIN is still set defensively
20	# in docker-compose.yml in case anything ever calls apps/api directly).
21	
22	worker_processes 1;
23	
24	events {
25	  worker_connections 256;
26	}
27	
28	http {
29	  server {
30	    listen 80;
31	
32	    # Dedicated, non-proxied location so this service's OWN Compose
33	    # healthcheck does not depend on apps/web or apps/api being ready too
34	    # (see docker-compose.yml's `nginx` healthcheck).
35	    location = /nginx-health {
36	      default_type text/plain;
37	      return 200 "ok\n";
38	    }
39	
40	    # Prefix stripped by the trailing slash on both the location and the
41	    # proxy_pass target: a request to /api/health reaches apps/api as
42	    # GET /health, matching apps/api/src/app.ts's actual routes (/,
43	    # /health, /ready). apps/api's own port is never published directly.
44	    location /api/ {
45	      proxy_pass http://api:3001/;
46	      proxy_http_version 1.1;
47	      proxy_set_header Host $host;
48	      proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
49	      proxy_set_header X-Forwarded-Proto $scheme;
50	    }
51	
52	    # Everything else goes to the Next.js dev server, including the
53	    # WebSocket upgrade its HMR client uses.
54	    location / {
55	      proxy_pass http://web:3000;
56	      proxy_http_version 1.1;
57	      proxy_set_header Upgrade $http_upgrade;
58	      proxy_set_header Connection "upgrade";
59	      proxy_set_header Host $host;
60	      proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
61	      proxy_set_header X-Forwarded-Proto $scheme;
62	    }
63	  }
64	}
