# Local-development reverse proxy. Prescribed by
# context/project-structure.md's required docker/ tree
# (docker/nginx/nginx.conf) — nginx is the required proxy technology, not
# an open choice (see docs/architecture/local-stack-inventory.md §8).
#
# This is a minimal dev-only config: no TLS, no caching, no production
# hardening, no rate limiting. It exists only to:
#   1. Give the browser ONE host-reachable origin for both the web app
#      and the API, so NEXT_PUBLIC_API_URL can point here instead of at
#      apps/api's internal container port (which is never published to
#      the host — see docker-compose.yml and
#      docs/architecture/docker-compose-stack.md).
#   2. Satisfy "expose health/readiness endpoints only through the local
#      reverse proxy" for apps/api's existing GET /health and GET /ready.
#
# Because both the page (served at "/") and the API (served at "/api/")
# are reached through this SAME origin, the browser's calls to
# NEXT_PUBLIC_API_URL become same-origin requests — no CORS exemption is
# relied upon for them to work (API_CORS_ORIGIN is still set defensively
# in docker-compose.yml in case anything ever calls apps/api directly).

worker_processes 1;

events {
  worker_connections 256;
}

http {
  server {
    listen 80;

    # Dedicated, non-proxied location so this service's OWN Compose
    # healthcheck does not depend on apps/web or apps/api being ready too
    # (see docker-compose.yml's `nginx` healthcheck).
    location = /nginx-health {
      default_type text/plain;
      return 200 "ok\n";
    }

    # Prefix stripped by the trailing slash on both the location and the
    # proxy_pass target: a request to /api/health reaches apps/api as
    # GET /health, matching apps/api/src/app.ts's actual routes (/,
    # /health, /ready). apps/api's own port is never published directly.
    location /api/ {
      proxy_pass http://api:3001/;
      proxy_http_version 1.1;
      proxy_set_header Host $host;
      proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
      proxy_set_header X-Forwarded-Proto $scheme;
    }

    # Everything else goes to the Next.js dev server, including the
    # WebSocket upgrade its HMR client uses.
    location / {
      proxy_pass http://web:3000;
      proxy_http_version 1.1;
      proxy_set_header Upgrade $http_upgrade;
      proxy_set_header Connection "upgrade";
      proxy_set_header Host $host;
      proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
      proxy_set_header X-Forwarded-Proto $scheme;
    }
  }
}

