1	import path from "node:path";
2	import { fileURLToPath } from "node:url";
3	import { afterAll, beforeAll, describe, expect, it } from "vitest";
4	import {
5	  type ComposeProject,
6	  cleanupComposeProject,
7	  composeExec,
8	  composeLogs,
9	  composePort,
10	  composeUp,
11	  createBucket,
12	  getContainerStatus,
13	  getFreePort,
14	  getS3Object,
15	  isDockerAvailableSync,
16	  putS3Object,
17	  uniqueProjectName,
18	  waitForExitCode,
19	  waitForHealthy,
20	  waitForHttpOk,
21	} from "@relis/test-utils";
22	
23	// Real, disposable-stack smoke check for ALL seven service
24	// responsibilities (see docker-compose.yml's header comment). Proves,
25	// against actual running containers (never mocks):
26	//   - web, api, worker, postgres, nginx, mailhog, and storage all start
27	//     as real processes/containers and (where a healthcheck exists)
28	//     report healthy.
29	//   - migrate-control / migrate-project ACTUALLY exit 0 (via
30	//     `docker inspect`'s real State.ExitCode, not "a database with the
31	//     right name exists" — docker/postgres/init/ creates both databases
32	//     unconditionally regardless of whether either migration ever runs),
33	//     AND provision two DISTINCT, isolated disposable databases
34	//     (Control DB + project-test target) — isolation verified by
35	//     creating a table in one and confirming its absence in the other.
36	//   - The browser-facing path works THROUGH the proxy only: apps/api's
37	//     port is never published; /health and /ready are only reached via
38	//     nginx's /api/ prefix. The frontend's OWN configured
39	//     NEXT_PUBLIC_API_URL is read back from the real running `web`
40	//     container (not assumed), and a plain Node `fetch` to that same URL
41	//     succeeds through the proxy. This is a CONFIGURATION and
42	//     HOST-SIDE-CONNECTIVITY proof only — it does not execute the
43	//     frontend's own browser JavaScript, so it is not evidence that a
44	//     real browser's request succeeds or that the UI reaches its success
45	//     state. That claim belongs to, and is proved by,
46	//     tests/e2e/docker-compose/web-health-check.spec.ts (a real
47	//     Playwright browser), not this file.
48	//   - apps/worker's existing `dev` process (tsx watch) is actually
49	//     running (watcher liveness) and completed its own startup/config
50	//     path (its log line) — explicitly NOT claimed as job processing;
51	//     no queue consumer exists or is added here.
52	//   - A real SeaweedFS S3-gateway upload/download round-trip, signed
53	//     with the development-only credentials in
54	//     docker/storage/s3-identities.json — NOT merely "the container
55	//     started." The SigV4 signer itself (packages/test-utils/src/s3-sigv4.ts)
56	//     was not previously executed against a live server; this is its
57	//     first real exercise.
58	//
59	// Uses a uniquely-named Compose project. NGINX_HTTP_PORT is a REAL free
60	// port chosen with getFreePort() BEFORE `up` (not the host-port-0
61	// "discover afterward" pattern used for MAILHOG_UI_PORT/SEAWEEDFS_S3_PORT
62	// below — see getFreePort's own doc comment for why NGINX_HTTP_PORT is
63	// different: it is baked into NEXT_PUBLIC_API_URL at container start, so
64	// "0" would bake in the broken "http://localhost:0/api"). This never
65	// collides with an already-running dev stack. Tears down (containers +
66	// volumes) for THIS project only in afterAll — never touches unrelated
67	// containers.
68	//
69	// Does NOT assert anything about job processing (apps/worker has no
70	// queue consumer in either mode — see docker-compose.yml's comment) and
71	// does NOT expect apps/api's static /ready to detect a database outage
72	// (see dependency-unavailable.test.ts for that boundary instead).
73	//
74	// Requires the `docker` CLI and a reachable daemon; skips (never mocks)
75	// when absent.
76	
77	const here = path.dirname(fileURLToPath(import.meta.url));
78	const repoRoot = path.resolve(here, "../../..");
79	const composeFile = path.join(repoRoot, "docker-compose.yml");
80	
81	const STORAGE_CREDENTIALS = { accessKey: "relis-dev-access", secretKey: "relis-dev-secret-key-local-only" };
82	const TEST_BUCKET = "relis-smoke-test";
83	const TEST_KEY = `smoke-${Date.now()}.txt`;
84	const TEST_BODY = Buffer.from(`relis compose smoke check ${new Date().toISOString()}`, "utf8");
85	
86	// Computed synchronously at module/collection time — see
87	// isDockerAvailableSync's own doc comment for why an async check in a
88	// beforeAll cannot gate describe.runIf/skipIf correctly.
89	const dockerAvailable = isDockerAvailableSync();
90	
91	if (!dockerAvailable) {
92	  // eslint-disable-next-line no-console
93	  console.warn(
94	    "[docker-compose/stack-smoke.test.ts] SKIPPED: the `docker` CLI is not available (or no daemon is reachable) " +
95	      "in this environment. No real container startup was verified; this is a reported blocker, not a pass.",
96	  );
97	}
98	
99	describe.runIf(dockerAvailable)("disposable stack smoke check", () => {
100	  const project: ComposeProject = { projectName: uniqueProjectName("relis-smoke"), composeFile, cwd: repoRoot };
101	
102	  let nginxPort: number;
103	  let migrateControlExitCode: number;
104	  let migrateProjectExitCode: number;
105	
106	  beforeAll(async () => {
107	    // NGINX_HTTP_PORT must be a REAL port chosen before `up`, not the
108	    // ephemeral-port placeholder "0": it is baked directly into
109	    // NEXT_PUBLIC_API_URL on the `web` service at container start (see
110	    // docker-compose.yml), so passing "0" through unresolved would bake
111	    // the broken "http://localhost:0/api" into the running container —
112	    // see getFreePort's own doc comment for why this differs from
113	    // MAILHOG_UI_PORT/SEAWEEDFS_S3_PORT below (neither is read by any
114	    // application code, so discovering their real port AFTER `up` is
115	    // fine for those two).
116	    nginxPort = await getFreePort();
117	    const env = {
118	      NGINX_HTTP_PORT: String(nginxPort),
119	      MAILHOG_UI_PORT: "0",
120	      SEAWEEDFS_S3_PORT: "0",
121	      PROJECT_TEST_DB_NAME: "relis_project_smoke_test",
122	    };
123	
124	    const up = await composeUp(project, env, [], { build: true, timeoutMs: 600000 });
125	    if (up.exitCode !== 0) {
126	      throw new Error(`docker compose up failed (exit ${up.exitCode}):\n${up.stdout}\n${up.stderr}`);
127	    }
128	    await Promise.all([
129	      waitForHealthy(project, "postgres"),
130	      waitForHealthy(project, "api"),
131	      waitForHealthy(project, "web"),
132	      waitForHealthy(project, "nginx"),
133	      waitForHealthy(project, "storage"),
134	    ]);
135	    // mailhog has no Compose healthcheck (see docker-compose.yml) — poll
136	    // its own HTTP port from the test side instead.
137	    const mailhogPort = await composePort(project, "mailhog", 8025);
138	    await waitForHttpOk(`http://127.0.0.1:${mailhogPort}/`);
139	
140	    // Block until both one-shot migration containers have actually
141	    // EXITED (not merely "a database with the right name exists" — see
142	    // the dedicated test below for why that is a different, insufficient
143	    // claim) before any test runs, so later assertions never race a
144	    // still-running migration.
145	    [migrateControlExitCode, migrateProjectExitCode] = await Promise.all([
146	      waitForExitCode(project, "migrate-control"),
147	      waitForExitCode(project, "migrate-project"),
148	    ]);
149	  }, 600000);
150	
151	  afterAll(async () => {
152	    // Throws (reporting the exact exit code/output) if cleanup itself
153	    // fails, instead of silently leaving this project's containers,
154	    // network, or volumes behind. If a setup/test step already failed,
155	    // Vitest records that failure independently of whatever this hook
156	    // does — a cleanup failure here is reported as an ADDITIONAL
157	    // failure, never a replacement for it.
158	    await cleanupComposeProject(project, { timeoutMs: 180000 });
159	  }, 180000);
160	
161	  it("provisions two distinct, isolated disposable databases", async () => {
162	    const createTable = await composeExec(project, "postgres", [
163	      "psql",
164	      "-U",
165	      "relis",
166	      "-d",
167	      "relis_control",
168	      "-c",
169	      "CREATE TABLE smoke_marker (id int);",
170	    ]);
171	    expect(createTable.exitCode, createTable.stderr).toBe(0);
172	
173	    const controlHasTable = await composeExec(project, "postgres", [
174	      "psql",
175	      "-U",
176	      "relis",
177	      "-d",
178	      "relis_control",
179	      "-tAc",
180	      "SELECT to_regclass('public.smoke_marker') IS NOT NULL;",
181	    ]);
182	    expect(controlHasTable.stdout.trim()).toBe("t");
183	
184	    // The table created in relis_control must NOT be visible from the
185	    // project-test database — this is the actual isolation proof, not
186	    // just two differently-named databases existing.
187	    const projectHasTable = await composeExec(project, "postgres", [
188	      "psql",
189	      "-U",
190	      "relis",
191	      "-d",
192	      "relis_project_smoke_test",
193	      "-tAc",
194	      "SELECT to_regclass('public.smoke_marker') IS NULL;",
195	    ]);
196	    expect(projectHasTable.stdout.trim()).toBe("t");
197	  });
198	
199	  it("runs migrate-control and migrate-project to completion with real exit code 0", () => {
200	    // NOT the same claim as "the database exists" (see the isolation
201	    // test above, and docker/postgres/init/ which creates BOTH databases
202	    // unconditionally on first init, independently of whether either
203	    // migration container ever runs or succeeds). migrateControlExitCode
204	    // / migrateProjectExitCode come from `docker inspect`'s real
205	    // State.ExitCode (waitForExitCode, in beforeAll) — the actual outcome
206	    // of `pnpm --filter @relis/database run migrate <target>`, not a
207	    // proxy for it.
208	    expect(migrateControlExitCode).toBe(0);
209	    expect(migrateProjectExitCode).toBe(0);
210	  });
211	
212	  it("reaches apps/api's health and readiness ONLY through the nginx proxy", async () => {
213	    const health = await fetch(`http://127.0.0.1:${nginxPort}/api/health`);
214	    expect(health.status).toBe(200);
215	    const healthBody = (await health.json()) as { status: string };
216	    expect(healthBody.status).toBe("ok");
217	
218	    const ready = await fetch(`http://127.0.0.1:${nginxPort}/api/ready`);
219	    expect(ready.status).toBe(200);
220	    const readyBody = (await ready.json()) as { status: string; checks: Record<string, string> };
221	    expect(readyBody.status).toBe("ok");
222	    // Matches apps/api/src/app.ts's actual, honest readiness contract: it
223	    // only reports network/cors, never a database/queue it does not have.
224	    expect(readyBody.checks).toEqual({ network: "ok", cors: "ok" });
225	  });
226	
227	  it("serves the web app through the same proxy origin as the API (browser-public address)", async () => {
228	    const page = await fetch(`http://127.0.0.1:${nginxPort}/`);
229	    expect(page.status).toBe(200);
230	  });
231	
232	  it("[config + host-side connectivity only — NOT a browser check] gives the frontend a real NEXT_PUBLIC_API_URL, and that URL is independently reachable through the proxy via plain Node fetch", async () => {
233	    // IMPORTANT — what this test does and does NOT prove:
234	    // It reads the ACTUAL NEXT_PUBLIC_API_URL the running `web` container
235	    // was given (ground truth, not an assumption) and then issues its
236	    // OWN plain Node `fetch`, from the test process, to the same URL the
237	    // browser WOULD use. That proves (a) the baked-in configuration is
238	    // correct (the real nginx port, never the ephemeral-port placeholder
239	    // "0" that NGINX_HTTP_PORT=0 would otherwise leak into it — see
240	    // getFreePort's doc comment) and (b) that URL is genuinely reachable
241	    // through the proxy from outside the Compose network.
242	    // It does NOT prove a real browser's JavaScript execution ever makes
243	    // this request, nor that the resulting UI reaches its success state.
244	    // That is a DIFFERENT claim, proved separately — with an actual
245	    // browser, observing the actual request the page's own client code
246	    // issues, and the resulting UI — by
247	    // tests/e2e/docker-compose/web-health-check.spec.ts.
248	    const envResult = await composeExec(project, "web", ["sh", "-c", "printenv NEXT_PUBLIC_API_URL"]);
249	    expect(envResult.exitCode, envResult.stderr).toBe(0);
250	    const configuredApiUrl = envResult.stdout.trim();
251	    expect(configuredApiUrl).toBe(`http://localhost:${nginxPort}/api`);
252	    expect(configuredApiUrl).not.toContain(":0/");
253	
254	    // A plain Node-side fetch to the same URL — a host-side connectivity
255	    // check, not a substitute for the browser actually issuing it.
256	    const response = await fetch(`${configuredApiUrl}/health`);
257	    expect(response.status).toBe(200);
258	    const body = (await response.json()) as { status: string };
259	    expect(body.status).toBe("ok");
260	  });
261	
262	  it("runs the worker's existing dev process (tsx watch) and completes its config/startup path — not evidence of job processing", async () => {
263	    // "running" here is the tsx watch SUPERVISOR staying alive after the
264	    // wrapped script's own log-and-return (see docker-compose.yml's
265	    // comment and docs/architecture/local-stack-inventory.md §3.3) — it
266	    // is watcher liveness, not a job being processed. No queue consumer
267	    // is added or implied by this assertion.
268	    const status = await getContainerStatus(project, "worker");
269	    expect(status).toBe("running");
270	
271	    // Proves loadWorkerConfig() actually succeeded and main() executed
272	    // its startup path (not merely that the container didn't crash on
273	    // the way up) — apps/worker/src/main.ts's own log line.
274	    const logs = await composeLogs(project, "worker");
275	    expect(logs.stdout).toContain("ReLiS worker started");
276	  });
277	
278	  it("captures mail-capture's web UI as a reachable development-only endpoint", async () => {
279	    const mailhogPort = await composePort(project, "mailhog", 8025);
280	    const ui = await fetch(`http://127.0.0.1:${mailhogPort}/`);
281	    expect(ui.status).toBe(200);
282	  });
283	
284	  it("performs a real, credentialed object-storage upload and download round-trip", async () => {
285	    const storagePort = await composePort(project, "storage", 8333);
286	    const target = { endpoint: `http://127.0.0.1:${storagePort}`, bucket: TEST_BUCKET, key: TEST_KEY };
287	
288	    // Disposable bucket setup: issued explicitly rather than relying on
289	    // SeaweedFS's own auto-vivify-on-first-PUT convenience, which is not
290	    // part of the S3 API contract (see createBucket's doc comment).
291	    const createBucketResponse = await createBucket(target, STORAGE_CREDENTIALS);
292	    expect(createBucketResponse.status, await createBucketResponse.text().catch(() => "")).toBeLessThan(300);
293	
294	    const putResponse = await putS3Object(target, STORAGE_CREDENTIALS, TEST_BODY);
295	    expect(putResponse.status, await putResponse.text().catch(() => "")).toBeLessThan(300);
296	
297	    const getResponse = await getS3Object(target, STORAGE_CREDENTIALS);
298	    expect(getResponse.status).toBe(200);
299	    const roundTripped = Buffer.from(await getResponse.arrayBuffer());
300	    expect(roundTripped.equals(TEST_BODY)).toBe(true);
301	  });
302	});
303	
304	describe.skipIf(dockerAvailable)("disposable stack smoke check (blocked)", () => {
305	  it("is a reported blocker, not executed, when Docker is unavailable", () => {
306	    expect(dockerAvailable).toBe(false);
307	  });
308	});
309

