265	 * "exited", "created", ...) — not Compose's own healthcheck status (see
266	 * `waitForHealthy` for that). Used to confirm actual process liveness for
267	 * a service with no healthcheck (e.g. `worker`, which has none — see
268	 * docker-compose.yml's comment on why).
269	 */
270	export async function getContainerStatus(project: ComposeProject, service: string): Promise<string> {
271	  const containerId = await getContainerId(project, service);
272	  if (!containerId) {
273	    throw new Error(`No container found for service "${service}" in project ${project.projectName}`);
