279	/**
280	 * Polls `docker inspect` for `service`'s container until its lifecycle
281	 * status is "exited", then returns its real `State.ExitCode` — the
282	 * actual outcome of the command the container ran, not a proxy for it
283	 * (e.g. not "a database it creates exists", which can be true regardless
284	 * of whether the command itself succeeded — see docker/postgres/init/,
285	 * which creates databases independently of migrate-control/migrate-project
286	 * ever running at all).
287	 */
288	export async function waitForExitCode(project: ComposeProject, service: string, timeoutMs = 120000): Promise<number> {
289	  const start = Date.now();
290	  while (Date.now() - start < timeoutMs) {
291	    const containerId = await getContainerId(project, service);
292	    if (containerId) {
293	      const inspect = await runToCompletion(
294	        "docker",
295	        ["inspect", containerId, "--format", "{{.State.Status}}|{{.State.ExitCode}}"],
296	        { timeoutMs: 15000 },
297	      );
298	      const [status, exitCodeRaw] = inspect.stdout.trim().split("|");
299	      if (status === "exited") {
300	        return Number(exitCodeRaw);
301	      }
302	    }
303	    await new Promise((resolveDelay) => setTimeout(resolveDelay, 1000));
304	  }
305	  throw new Error(`Timed out after ${timeoutMs}ms waiting for service "${service}" to exit in project ${project.projectName}`);
306	}
