308	/**
309	 * Polls `url` with plain HTTP GET requests until it responds (any status
310	 * code — this only proves the server is accepting connections, not that
311	 * the endpoint itself is semantically "ok"), or `timeoutMs` elapses. Used
312	 * for a service with no Compose `healthcheck:` block (e.g. `mailhog` —
313	 * see docker-compose.yml's comment on why) instead of fabricating one.
314	 */
315	export async function waitForHttpOk(url: string, timeoutMs = 60000): Promise<void> {
316	  const start = Date.now();
317	  let lastError: unknown;
318	  while (Date.now() - start < timeoutMs) {
319	    try {
320	      await fetch(url);
321	      return;
322	    } catch (error) {
323	      lastError = error;
324	      await new Promise((resolveDelay) => setTimeout(resolveDelay, 1000));
325	    }
326	  }
327	  throw new Error(`Timed out after ${timeoutMs}ms waiting for ${url} to accept connections. Last error: ${String(lastError)}`);
328	}
