330	/**
331	 * Polls `docker compose ps` for `service` until its healthcheck reports
332	 * "(healthy)", or `timeoutMs` elapses. Relies on a real `healthcheck:`
333	 * block existing on that service in docker-compose.yml — never
334	 * fabricates readiness for a service with no healthcheck (e.g.
335	 * apps/worker, which has none — see docker-compose.yml's comment on why).
336	 */
337	export async function waitForHealthy(project: ComposeProject, service: string, timeoutMs = 120000): Promise<void> {
338	  const start = Date.now();
339	  while (Date.now() - start < timeoutMs) {
340	    const result = await runToCompletion("docker", composeArgs(project, ["ps", service]), {
341	      cwd: project.cwd,
342	      timeoutMs: 15000,
343	    });
344	    const serviceLine = result.stdout.split("\n").find((line) => line.includes(service));
345	    if (serviceLine?.includes("(healthy)")) return;
346	    if (serviceLine?.includes("(unhealthy)")) {
347	      throw new Error(`Service "${service}" reported unhealthy in project ${project.projectName}:\n${result.stdout}`);
348	    }
349	    await new Promise((resolveDelay) => setTimeout(resolveDelay, 1000));
350	  }
351	  throw new Error(`Timed out after ${timeoutMs}ms waiting for service "${service}" to become healthy in project ${project.projectName}`);
352	}
