429	export interface VolumeOwnership {
430	  name: string;
431	  driver: string;
432	  /** `com.docker.compose.project` — which Compose project created it. */
433	  composeProject: string | undefined;
434	  /** `com.docker.compose.volume` — which volume key declared in docker-compose.yml it implements. */
435	  composeVolumeKey: string | undefined;
436	  /** Every label, for diagnosis. Compose's own labels carry no secret values. */
