440	/**
441	 * Matches Docker's own, specific "no such volume" error line (confirmed
442	 * against the real CLI: `docker volume inspect <missing-name>` exits 1
443	 * with stderr `Error response from daemon: get <name>: no such volume`).
444	 * This is the ONLY signal `inspectVolume` treats as genuine absence —
445	 * exported so the classification itself can be unit-tested with
446	 * synthetic stderr text, without a real Docker daemon. Every other
447	 * nonzero-exit stderr (a daemon unreachable error, a permission
448	 * failure, or anything else) does NOT match, so it is treated as a real
449	 * failure by `inspectVolume`, never as absence.
450	 */
451	export function isVolumeNotFoundError(stderr: string): boolean {
452	  return /no such volume/i.test(stderr);
453	}
454	
455	/**
456	 * `docker volume inspect` for one volume.
457	 *
458	 * Returns `undefined` ONLY for a genuine "no such volume" response (see
459	 * `isVolumeNotFoundError`) — never for any other nonzero exit. A daemon
460	 * that is unreachable, a permission failure, or any other command
461	 * failure THROWS instead, naming the exit code and stderr. Malformed
462	 * output on a zero exit (unparseable JSON) also throws rather than being
463	 * swallowed. This matters specifically because `volumeExists` (below)
464	 * delegates to this function: without this distinction, an inspection
465	 * FAILURE could silently read as "the volume does not exist," which
466	 * would let a caller wrongly treat a failed check as proof a volume was
467	 * deleted.
468	 */
469	export async function inspectVolume(name: string): Promise<VolumeOwnership | undefined> {
470	  const result = await runToCompletion("docker", ["volume", "inspect", name, "--format", "{{json .}}"], { timeoutMs: 30000 });
471	  if (result.exitCode !== 0) {
472	    if (isVolumeNotFoundError(result.stderr)) return undefined;
473	    throw new Error(
474	      `docker volume inspect "${name}" failed (exit ${result.exitCode}) and is NOT a "no such volume" response — ` +
475	        `refusing to treat this as absence:\nstderr:\n${result.stderr}\nstdout:\n${result.stdout}`,
476	    );
477	  }
478	  let raw: { Name: string; Driver: string; Labels: Record<string, string> | null };
479	  try {
480	    raw = JSON.parse(result.stdout.trim()) as { Name: string; Driver: string; Labels: Record<string, string> | null };
481	  } catch (error) {
482	    throw new Error(
483	      `docker volume inspect "${name}" exited 0 but its output could not be parsed as JSON: ${String(error)}\nstdout:\n${result.stdout}`,
484	    );
485	  }
486	  const labels = raw.Labels ?? {};
487	  return {
488	    name: raw.Name,
489	    driver: raw.Driver,
490	    composeProject: labels["com.docker.compose.project"],
491	    composeVolumeKey: labels["com.docker.compose.volume"],
492	    labels,
493	  };
494	}
