496	/**
497	 * Whether `name` currently exists. Delegates entirely to `inspectVolume`,
498	 * so an inspection FAILURE (daemon unreachable, permission denied,
499	 * malformed output) propagates as a thrown error here too, rather than
500	 * resolving to `false` — a caller asserting "this volume was deleted"
501	 * must never have that assertion pass merely because the check itself
502	 * failed.
503	 */
504	export async function volumeExists(name: string): Promise<boolean> {
505	  return (await inspectVolume(name)) !== undefined;
506	}
507	
508	export interface VolumeDeletionCheck {
509	  name: string;
510	  ok: boolean;
511	  /** Present when `ok` is false — the exact reason deletion was refused, for a "requires manual inspection" report. */
512	  reason?: string;
513	}
514	
515	export interface VolumeOwnershipContext {
516	  /** The Compose project this volume is expected to be labelled with. */
517	  expectedProjectName: string;
518	  /** Volume names that already existed on the daemon before this run started — see `listAllVolumeNames`. */
519	  baselineVolumeNames: readonly string[];
520	  /** Volume KEYS (docker-compose.yml's own `volumes:` keys, e.g. "postgres-data") declared `external: true` — a pre-existing user resource, never one this stack created. */
521	  externalVolumeKeys: readonly string[];
522	}
523	
524	/**
525	 * The three — and only three — outcomes inspecting one volume name can
526	 * have, kept explicitly distinct so a destructive gate can never
527	 * confuse one for another:
528	 *   - `"exists"` — the volume is really there, with its real ownership.
529	 *   - `"absent"` — the daemon CONFIRMED no such volume exists (see
530	 *     `isVolumeNotFoundError`). There is nothing to delete and nothing
531	 *     to protect: this must never block a destructive step.
532	 *   - `"failed"` — inspecting it did not succeed at all (daemon
533	 *     unreachable, permission denied, malformed output — see
534	 *     `inspectVolume`'s own contract). This is NOT the same as absence
535	 *     and MUST block a destructive step: the volume could exist and we
536	 *     simply don't know.
537	 */
538	export type VolumeInspectionResult =
539	  | { status: "exists"; ownership: VolumeOwnership }
540	  | { status: "absent" }
541	  | { status: "failed"; error: string };
542	
543	/** One volume name that had to be considered, together with how inspecting it actually went. */
544	export interface OwnedVolumeRecord {
545	  name: string;
546	  inspection: VolumeInspectionResult;
547	}
548	
549	/**
550	 * Pure ownership gate for ONE volume, given an already-fetched
551	 * inspection result: it never queries the daemon itself, which is what
552	 * makes it independently unit-testable with constructed fakes (no real
553	 * Docker, no risk to any real volume).
554	 *
555	 * - `"absent"` is always `ok: true` — a CONFIRMED absence is not a
556	 *   reason to block anything; there is simply nothing there to delete.
557	 * - `"failed"` is always `ok: false` — an inspection FAILURE must never
558	 *   be treated as "safe to proceed," because the volume might still be
559	 *   there.
560	 * - `"exists"` is `ok: true` only when ALL of: the volume is NOT in
561	 *   `context.baselineVolumeNames` (it did not already exist before this
562	 *   run); its `com.docker.compose.project` label matches
563	 *   `context.expectedProjectName` exactly (it belongs to THIS disposable
564	 *   project, not a development stack or another project, and never a
565	 *   name-prefix guess); and its `com.docker.compose.volume` key is not
566	 *   one of `context.externalVolumeKeys` (not declared `external: true`,
567	 *   which would make it a pre-existing resource regardless of its
568	 *   labels).
569	 */
570	export function checkVolumeOwnershipForDeletion(
571	  name: string,
572	  inspection: VolumeInspectionResult,
573	  context: VolumeOwnershipContext,
574	): VolumeDeletionCheck {
575	  if (inspection.status === "absent") {
576	    return { name, ok: true };
577	  }
578	  if (inspection.status === "failed") {
579	    return { name, ok: false, reason: `could not be inspected: ${inspection.error}` };
580	  }
581	  const { ownership } = inspection;
582	  if (context.baselineVolumeNames.includes(name)) {
583	    return { name, ok: false, reason: "already existed on the daemon before this run started — it is a pre-existing resource" };
584	  }
585	  if (ownership.composeProject !== context.expectedProjectName) {
586	    return {
587	      name,
588	      ok: false,
589	      reason:
590	        `labelled com.docker.compose.project="${ownership.composeProject ?? "(none)"}", not the expected disposable ` +
591	        `project "${context.expectedProjectName}" — it may belong to a development stack or another user resource`,
592	    };
593	  }
594	  if (ownership.composeVolumeKey !== undefined && context.externalVolumeKeys.includes(ownership.composeVolumeKey)) {
595	    return {
596	      name,
597	      ok: false,
598	      reason: `implements volume key "${ownership.composeVolumeKey}", declared external:true — a pre-existing user resource`,
599	    };
600	  }
601	  return { name, ok: true };
602	}
603	
604	export interface OwnershipGateResult {
605	  ok: boolean;
606	  checks: VolumeDeletionCheck[];
607	}
608	
609	/**
610	 * The hard gate a destructive reset or cleanup must pass before
611	 * `--volumes` is ever issued: PURE and synchronous — it only classifies
612	 * already-fetched `records` (see `discoverVolumesRequiringInspection`
613	 * for how those are built), which is what makes it independently
614	 * unit-testable with constructed fakes. `ok` is true only when EVERY
615	 * record passes `checkVolumeOwnershipForDeletion`. An EMPTY `records`
616	 * list is itself refused — there is nothing to establish ownership of,
617	 * which must never be read as "nothing to check, proceed."
618	 */
619	export function evaluateOwnershipGate(records: readonly OwnedVolumeRecord[], context: VolumeOwnershipContext): OwnershipGateResult {
620	  if (records.length === 0) {
621	    return {
622	      ok: false,
623	      checks: [{ name: "(none)", ok: false, reason: "no volume was identified for this project — ownership cannot be established" }],
624	    };
625	  }
626	  const checks = records.map((record) => checkVolumeOwnershipForDeletion(record.name, record.inspection, context));
627	  return { ok: checks.every((check) => check.ok), checks };
628	}
