630	export interface VolumeDiscoverySources {
631	  /**
632	   * The EXACT volume names `docker compose down --volumes` would target
633	   * for this project — i.e. a FRESH read of `resolveComposePersistence`'s
634	   * `volumeNames` values, using the SAME Compose file/project/env the
635	   * destructive step itself will use. MUST reject (never resolve to a
636	   * partial or stale list) when the configuration cannot be resolved —
637	   * `discoverVolumesRequiringInspection` propagates that rejection so
638	   * the caller fails closed.
639	   */
640	  resolveConfiguredVolumeNames: () => Promise<string[]>;
641	  /** Volume names the daemon's own `com.docker.compose.project` label filter reports for this project (e.g. `listVolumeNamesByComposeProject`). */
642	  listLabeledVolumeNames: () => Promise<string[]>;
643	  /** Inspects one volume name. Resolves to `undefined` ONLY for a CONFIRMED absence; any other failure must throw (see `inspectVolume`'s own contract). */
644	  inspectVolumeByName: (name: string) => Promise<VolumeOwnership | undefined>;
645	}
646	
647	/**
648	 * Builds the full, de-duplicated set of volume names that MUST be
649	 * inspected before a destructive cleanup, and inspects every one.
650	 *
651	 * The set is the UNION of:
652	 *   - the volume names resolved from the EXACT Compose configuration the
653	 *     destructive step will use (`resolveConfiguredVolumeNames`) — this
654	 *     is what `docker compose down --volumes` actually targets, by
655	 *     NAME; and
656	 *   - whatever the daemon's own project-LABEL filter additionally
657	 *     reports (`listLabeledVolumeNames`).
658	 * Label-based discovery ALONE is not enough to gate a destructive step:
659	 * a volume whose NAME matches what Compose will target, but whose
660	 * `com.docker.compose.project` label is missing or wrong (created
661	 * out-of-band, relabeled, or a Compose/engine quirk), would never
662	 * appear in a label-filtered list — yet `docker compose down --volumes`
663	 * addresses volumes by NAME, not by label, and would still remove it.
664	 * The union closes exactly that gap.
665	 *
666	 * FAILS CLOSED: if EITHER `resolveConfiguredVolumeNames` or
667	 * `listLabeledVolumeNames` rejects, this rejects too, rather than
668	 * silently proceeding with whichever half succeeded — an INCOMPLETE
669	 * name set must never be treated as "nothing else to check." (Callers
670	 * such as `cleanupDisposableTargets` catch this and block the
671	 * destructive step for that target entirely, reporting the failure.)
672	 *
673	 * A single name's OWN inspection failure, by contrast, does NOT abort
674	 * this whole function: once the complete name set is known, every name
675	 * is inspected independently, and a failure for one is recorded as that
676	 * record's own `{status:"failed"}` (see `VolumeInspectionResult`) so
677	 * every other volume's real status is still reported — never silently
678	 * dropped, and never confused with a confirmed `"absent"`.
679	 */
680	export async function discoverVolumesRequiringInspection(sources: VolumeDiscoverySources): Promise<OwnedVolumeRecord[]> {
681	  const [configuredNames, labeledNames] = await Promise.all([sources.resolveConfiguredVolumeNames(), sources.listLabeledVolumeNames()]);
682	  const unionNames = Array.from(new Set([...configuredNames, ...labeledNames]));
683	  return Promise.all(
684	    unionNames.map(async (name): Promise<OwnedVolumeRecord> => {
685	      try {
686	        const ownership = await sources.inspectVolumeByName(name);
687	        return { name, inspection: ownership ? { status: "exists", ownership } : { status: "absent" } };
688	      } catch (error) {
689	        return { name, inspection: { status: "failed", error: String(error) } };
690	      }
691	    }),
692	  );
693	}
