700	/**
701	 * Validates a RESOLVED Compose configuration is safe to provision as a
702	 * disposable project — called BEFORE any container or volume is
703	 * created, using only the static `docker compose config` output (no
704	 * daemon query, which is what makes this pure and unit-testable with a
705	 * constructed `ResolvedComposePersistence`). Every declared volume must:
706	 *   - Resolve to a name actually prefixed by the project's own name
707	 *     (`<project>_<key>` or `<project>-<key>`), so it cannot collide
708	 *     with a different project's volume.
709	 *   - Not be declared `external: true` — that would point at a
710	 *     pre-existing user resource this stack must never create or
711	 *     destroy.
712	 *   - Not already exist on the daemon (the pre-captured baseline) —
713	 *     catches the one scenario volume-name-prefixing alone cannot: a
714	 *     volume that, by coincidence or a reused project name, already
715	 *     exists under the exact name this run is about to use.
716	 */
717	export function checkProvisioningSafety(
718	  resolved: ResolvedComposePersistence,
719	  baselineVolumeNames: readonly string[],
720	): ProvisioningSafetyCheck {
721	  const problems: string[] = [];
722	  if (resolved.externalVolumes.length > 0) {
723	    problems.push(`volume key(s) declared external:true: ${resolved.externalVolumes.join(", ")} — refusing a pre-existing resource`);
724	  }
725	  for (const [key, name] of Object.entries(resolved.volumeNames)) {
726	    if (!name.startsWith(`${resolved.projectName}_`) && !name.startsWith(`${resolved.projectName}-`)) {
727	      problems.push(`volume "${name}" (key "${key}") is not scoped to project "${resolved.projectName}" by name`);
728	    }
729	    if (baselineVolumeNames.includes(name)) {
730	      problems.push(`volume "${name}" (key "${key}") already exists on the daemon before this run started`);
731	    }
732	  }
733	  return { ok: problems.length === 0, problems };
734	}
735	
736	/** `checkProvisioningSafety`, but throws — stopping short of provisioning anything — when the check fails. */
737	export function assertProvisioningSafety(resolved: ResolvedComposePersistence, baselineVolumeNames: readonly string[]): void {
738	  const check = checkProvisioningSafety(resolved, baselineVolumeNames);
739	  if (!check.ok) {
740	    throw new Error(`Refusing to provision disposable project "${resolved.projectName}":\n- ${check.problems.join("\n- ")}`);
741	  }
742	}
743	
744	/**
745	 * `composeDownKeepVolumes`, but throws on a nonzero exit instead of
746	 * returning a result the caller might forget to check. `options.env` is
747	 * forwarded to `composeDownKeepVolumes` unchanged.
748	 */
749	export async function removeContainersKeepingVolumesOrThrow(
750	  project: ComposeProject,
751	  options: { timeoutMs?: number; env?: ComposeEnv } = {},
752	): Promise<void> {
753	  const result = await composeDownKeepVolumes(project, options);
754	  if (result.exitCode !== 0) {
755	    throw new Error(
756	      `docker compose down (keeping volumes) failed for project "${project.projectName}" (exit ${result.exitCode}):\n` +
757	        `stdout:\n${result.stdout}\nstderr:\n${result.stderr}`,
758	    );
759	  }
760	}
761	
762	export interface DisposableCleanupTarget {
763	  /** Identifies this target in a reported outcome — typically the Compose project name. */
764	  label: string;
765	  /**
766	   * Produces the full set of volumes requiring inspection for this
767	   * target (see `discoverVolumesRequiringInspection` — the union of the
768	   * exact configured names and whatever label-based discovery reports,
769	   * each already paired with its inspection result). Resolving this
770	   * here, rather than inside `cleanupDisposableTargets` itself, is what
771	   * keeps that function's own decision logic pure and independently
772	   * unit-testable with constructed fakes — no real Docker call is
773	   * hard-wired into it. MUST reject (fail closed) rather than resolve
774	   * to a partial list when the underlying configuration cannot be
775	   * resolved — see `discoverVolumesRequiringInspection`'s own contract.
776	   */
777	  discoverVolumes: () => Promise<OwnedVolumeRecord[]>;
778	  /** Context used to verify EVERY discovered volume immediately before any is destroyed. */
779	  ownershipContext: VolumeOwnershipContext;
780	  /** Removes this target's containers/network but KEEPS its volumes. Always safe to call: it never touches another target's resources, and never deletes data. */
781	  removeContainersKeepingVolumes: () => Promise<void>;
782	  /** Removes this target's containers/network AND its named volumes. Only ever invoked by `cleanupDisposableTargets` after every discovered volume has passed the ownership gate. */
783	  removeContainersAndVolumes: () => Promise<void>;
784	}
785	
786	export interface DisposableCleanupOutcome {
787	  label: string;
788	  volumesDeleted: string[];
789	  volumesRequiringManualInspection: { name: string; reason: string }[];
790	  /** Set when something about processing this target itself failed (discovering its volumes, or either removal call) — includes a failed/fail-closed configuration resolution. */
791	  error?: string;
792	}
793	
794	/**
795	 * Cleans up multiple disposable targets independently and safely.
796	 *
797	 * For EACH target: discovers every volume that must be inspected
798	 * (`discoverVolumes` — the union of configured and label-discovered
799	 * names, never label discovery alone), then re-checks EVERY one of them
800	 * with the PURE `evaluateOwnershipGate` immediately before any
801	 * destructive step — never relying on an ownership check performed
802	 * earlier in the test run, since the exact resources present at cleanup
803	 * time are what matters. Only when EVERY volume passes is
804	 * `removeContainersAndVolumes` invoked; otherwise this REFUSES the
805	 * destructive step for that target entirely (removing only
806	 * containers/network, which is always safe since they belong solely to
807	 * that target's own Compose project) and reports exactly which volumes
808	 * require manual inspection, with why. Only volumes CONFIRMED to exist
809	 * are reported as `volumesDeleted` — a confirmed-absent one had nothing
810	 * to delete.
811	 *
812	 * A failure processing ONE target (discovering its volumes — including
813	 * a fail-closed configuration-resolution failure — or either removal
814	 * call throwing) is caught and reported in that target's own outcome —
815	 * it never stops or skips the other targets, which is what makes this
816	 * safe to use for partial setup (e.g. a target whose containers never
817	 * actually started).
818	 */
819	export async function cleanupDisposableTargets(targets: DisposableCleanupTarget[]): Promise<DisposableCleanupOutcome[]> {
820	  return Promise.all(
821	    targets.map(async (target): Promise<DisposableCleanupOutcome> => {
822	      try {
823	        const records = await target.discoverVolumes();
824	        const gate = evaluateOwnershipGate(records, target.ownershipContext);
825	        if (!gate.ok) {
826	          await target.removeContainersKeepingVolumes();
827	          return {
828	            label: target.label,
829	            volumesDeleted: [],
830	            volumesRequiringManualInspection: gate.checks
831	              .filter((check) => !check.ok)
832	              .map((check) => ({ name: check.name, reason: check.reason ?? "unknown" })),
833	          };
834	        }
835	
836	        await target.removeContainersAndVolumes();
837	        const volumesDeleted = records.filter((record) => record.inspection.status === "exists").map((record) => record.name);
838	        return { label: target.label, volumesDeleted, volumesRequiringManualInspection: [] };
839	      } catch (error) {
840	        return { label: target.label, volumesDeleted: [], volumesRequiringManualInspection: [], error: String(error) };
841	      }
842	    }),
843	  );
844	}
845	
846	/**
847	 * Builds a REAL, Docker-backed `DisposableCleanupTarget` for `project`.
848	 *
849	 * `discoverVolumes` re-resolves the Compose configuration FRESH, at the
850	 * moment cleanup actually runs — "the exact Compose configuration used
851	 * for cleanup" — rather than reusing a value cached from setup time;
852	 * a resolution failure there propagates (fails closed), which
853	 * `cleanupDisposableTargets` reports as this target's own `error`
854	 * without ever attempting a deletion. `externalVolumeKeys` on the
855	 * returned `ownershipContext` is read from a SEPARATE, best-effort
856	 * resolution (degrading to `[]` on failure) — this is only a secondary
857	 * signal for the ownership context; the baseline/project-label checks
858	 * remain the dominant guard, and the PRIMARY fail-closed behavior is
859	 * `discoverVolumes` above.
860	 *
861	 * `env` — the SAME `ComposeEnv` this function receives — is used for
862	 * BOTH halves of the gate/act pair: resolving the configuration
863	 * (`discoverVolumes`'s `resolveConfiguredVolumeNames` and the
864	 * `externalVolumeKeys` lookup above) AND the actual cleanup commands
865	 * (`removeContainersKeepingVolumes`/`removeContainersAndVolumes`
866	 * below). Environment overrides can change which volume names, ports,
867	 * or database targets a Compose project resolves to; a cleanup command
868	 * run under a DIFFERENT environment than the one its own gate just
869	 * validated could target a different, unverified configuration. Using
870	 * one single `env` value throughout this target is what rules that out.
871	 */
872	export async function createComposeCleanupTarget(
873	  project: ComposeProject,
874	  env: ComposeEnv,
875	  baselineVolumeNames: readonly string[],
876	): Promise<DisposableCleanupTarget> {
877	  const externalVolumeKeys = await resolveComposePersistence(project, env)
878	    .then((resolved) => resolved.externalVolumes)
879	    .catch(() => [] as string[]);
880	
881	  return {
882	    label: project.projectName,
883	    discoverVolumes: () =>
884	      discoverVolumesRequiringInspection({
885	        resolveConfiguredVolumeNames: () =>
886	          resolveComposePersistence(project, env).then((resolved) => Object.values(resolved.volumeNames)),
887	        listLabeledVolumeNames: () => listVolumeNamesByComposeProject(project),
888	        inspectVolumeByName: (name) => inspectVolume(name),
889	      }),
890	    ownershipContext: { expectedProjectName: project.projectName, baselineVolumeNames, externalVolumeKeys },
891	    // Both removal calls receive the SAME `env` this function was given
892	    // — the identical overrides `discoverVolumes` above uses to resolve
893	    // the configuration being torn down. This is the fix: a destructive
894	    // or volume-preserving cleanup command must never run against a
895	    // DIFFERENT environment than the one its own ownership gate just
896	    // validated against.
897	    removeContainersKeepingVolumes: () => removeContainersKeepingVolumesOrThrow(project, { timeoutMs: 180000, env }),
898	    removeContainersAndVolumes: () => cleanupComposeProject(project, { timeoutMs: 180000, env }),
899	  };
900	}
901	
902	export interface ComposeBindMount {
903	  source: string;
904	  target: string;
905	  readOnly: boolean;
906	}
907	
908	/** Host/port/database parsed out of a connection string — deliberately never its credentials or its raw value. */
909	export interface DatabaseTarget {
910	  host: string;
911	  port: string;
912	  database: string;
913	}
914	
915	export interface ResolvedComposePersistence {
916	  /** The Compose project name the resolved configuration will actually use. */
917	  projectName: string;
918	  /** Volume key declared in docker-compose.yml -> the real Docker volume name Compose will create. */
919	  volumeNames: Record<string, string>;
920	  /** Volume keys declared `external: true` — a pre-existing user resource a test must never delete. */
921	  externalVolumes: string[];
922	  /** Service name -> its bind mounts (host source path, container target, read-only flag). */
923	  bindMounts: Record<string, ComposeBindMount[]>;
924	  /** Service name -> `*_DATABASE_URL` variable -> its host/port/database. Credentials are discarded, never returned. */
925	  databaseTargets: Record<string, Record<string, DatabaseTarget>>;
926	}
927	
928	/**
929	 * Resolves the merged Compose configuration and extracts ONLY the
930	 * persistence facts a test needs: volume names and their external flag,
931	 * bind mounts, and the host/port/database of every `*_DATABASE_URL`.
932	 *
933	 * The underlying `docker compose config --format json` output echoes
934	 * every interpolated development-only placeholder in plaintext
935	 * (POSTGRES_PASSWORD, and the credentials embedded in each connection
936	 * string) — which is exactly why `composeConfigQuiet` exists. This
937	 * function therefore parses that document in-process and returns only
938	 * the narrow, credential-free shape above: it never returns it, logs it,
939	 * or includes it in an error message (a failure reports stderr only,
940	 * never stdout). Callers must preserve that property.
941	 *
942	 * Requires the `docker compose` CLI but NOT a running daemon.
943	 */
944	export async function resolveComposePersistence(project: ComposeProject, env: ComposeEnv): Promise<ResolvedComposePersistence> {
945	  const args = composeArgs(project, ["config", "--format", "json"]);
946	  const result = await runToCompletion("docker", args, { cwd: project.cwd, env: withEnv(env), timeoutMs: 60000 });
947	  if (result.exitCode !== 0) {
948	    throw new Error(`docker compose config --format json failed (exit ${result.exitCode}):\n${result.stderr}`);
949	  }
950	
951	  const parsed = JSON.parse(result.stdout) as {
952	    name?: string;
953	    volumes?: Record<string, { name?: string; external?: boolean } | null>;
954	    services?: Record<
955	      string,
956	      {
957	        volumes?: { type?: string; source?: string; target?: string; read_only?: boolean }[];
958	        environment?: Record<string, string | null>;
959	      }
960	    >;
961	  };
962	
963	  const volumeNames: Record<string, string> = {};
964	  const externalVolumes: string[] = [];
965	  for (const [key, definition] of Object.entries(parsed.volumes ?? {})) {
966	    volumeNames[key] = definition?.name ?? `${parsed.name ?? project.projectName}_${key}`;
967	    if (definition?.external === true) externalVolumes.push(key);
968	  }
969	
970	  const bindMounts: Record<string, ComposeBindMount[]> = {};
971	  const databaseTargets: Record<string, Record<string, DatabaseTarget>> = {};
972	  for (const [serviceName, service] of Object.entries(parsed.services ?? {})) {
973	    const binds = (service.volumes ?? [])
974	      .filter((mount) => mount.type === "bind")
975	      .map((mount) => ({ source: mount.source ?? "", target: mount.target ?? "", readOnly: mount.read_only === true }));
976	    if (binds.length > 0) bindMounts[serviceName] = binds;
977	
978	    for (const [variable, value] of Object.entries(service.environment ?? {})) {
979	      if (!variable.endsWith("_DATABASE_URL") || typeof value !== "string" || value.length === 0) continue;
980	      const url = new URL(value);
981	      databaseTargets[serviceName] ??= {};
982	      // hostname/port/pathname only — the username and password are dropped here and never leave this function.
983	      databaseTargets[serviceName][variable] = {
984	        host: url.hostname,
985	        port: url.port,
986	        database: url.pathname.replace(/^\//, ""),
987	      };
988	    }
989	  }
990	
991	  return { projectName: parsed.name ?? project.projectName, volumeNames, externalVolumes, bindMounts, databaseTargets };
992	}
