107	 * terminated (see `killDetachedProcessTree`), and the returned promise
108	 * only rejects once that termination is CONFIRMED by the child's own
109	 * "close" event (stdio streams closed, exit/signal known) — or, bounded
110	 * by `KILL_GRACE_MS`, reports that confirmation explicitly failed rather
111	 * than silently resolving or rejecting as if cleanup were already safe.
112	 * This matters specifically because a caller that tears down shared
113	 * infrastructure (e.g. a disposable Compose project) immediately after
114	 * this promise settles must never be racing a still-running startup
115	 * command that could keep creating resources after that teardown ran.
116	 */
117	export function runToCompletion(
118	  command: string,
119	  args: string[],
120	  options: SpawnOptions & { timeoutMs?: number } = {},
121	): Promise<SpawnResult> {
122	  const { timeoutMs = 30000, ...spawnOptions } = options;
123	
124	  return new Promise((resolve, reject) => {
125	    const child = spawn(toShellCommand(command, args), {
126	      ...spawnOptions,
127	      shell: true,
128	      // Detached on POSIX only: makes this child the leader of its OWN
129	      // process group, which killDetachedProcessTree relies on to
130	      // signal exactly this subtree on a timeout (see that function's
131	      // doc comment). A no-op distinction on Windows, where `detached`
132	      // means something unrelated (console allocation) and tree
133	      // relationships are tracked by the OS regardless — taskkill /T
134	      // already handles that case without this.
135	      ...(process.platform === "win32" ? {} : { detached: true }),
136	    });
