138	    let stdout = "";
139	    let stderr = "";
140	    let settled = false;
141	    let timedOut = false;
142	    let killGraceTimer: NodeJS.Timeout | undefined;
143	
144	    child.stdout?.on("data", (chunk: Buffer) => {
145	      stdout += chunk.toString();
146	    });
147	    child.stderr?.on("data", (chunk: Buffer) => {
148	      stderr += chunk.toString();
149	    });
150	
151	    const timer = setTimeout(() => {
152	      timedOut = true;
153	      killDetachedProcessTree(child.pid);
154	      // Bounded wait for the "close" handler below to confirm the kill
155	      // actually took effect. Deliberately does NOT resolve/reject here
156	      // itself on the happy path — "close" (the single listener below)
157	      // remains the only place that ever settles this promise, so there
158	      // is no risk of it firing concurrently with this timer and racing
159	      // which outcome (resolve vs. the intended timeout rejection) wins.
160	      killGraceTimer = setTimeout(() => {
161	        if (settled) return;
162	        settled = true;
163	        reject(
164	          new Error(
165	            `Process timed out after ${timeoutMs}ms and could NOT be confirmed terminated within ` +
166	              `${KILL_GRACE_MS}ms afterward: ${command} ${args.join(" ")}\n` +
