229	  let stdout = "";
230	  let stderr = "";
231	
232	  child.stdout.on("data", (chunk: Buffer) => {
233	    stdout += chunk.toString();
234	  });
235	  child.stderr.on("data", (chunk: Buffer) => {
236	    stderr += chunk.toString();
237	  });
238	
239	  async function waitForOutput(predicate: (combined: string) => boolean, timeoutMs = 30000): Promise<void> {
240	    const start = Date.now();
241	    while (Date.now() - start < timeoutMs) {
242	      if (predicate(stdout + stderr)) return;
243	      if (child.exitCode !== null) {
244	        throw new Error(
245	          `Process exited (code ${child.exitCode}) before expected output.\nstdout=${stdout}\nstderr=${stderr}`,
246	        );
247	      }
248	      await new Promise((resolveDelay) => setTimeout(resolveDelay, 200));
249	    }
250	    throw new Error(`Timed out waiting for expected output.\nstdout=${stdout}\nstderr=${stderr}`);
251	  }
252	
253	  async function stop(): Promise<void> {
254	    if (child.exitCode !== null) return;
255	    const pid = child.pid;
256	    await new Promise<void>((resolveStop) => {
257	      const timer = setTimeout(() => {
258	        killProcessTree(pid);
259	        resolveStop();
260	      }, 5000);
261	      child.once("exit", () => {
262	        clearTimeout(timer);
263	        resolveStop();
264	      });
265	      killProcessTree(pid);
266	    });
267	  }
268	
269	  return {
270	    child,
271	    stdout: () => stdout,
272	    stderr: () => stderr,
273	    waitForOutput,
274	    stop,
275	  };
276	}
